script:
(function () {
  'use strict';
  // Investment income from a portfolio, two ways:
  //   Yield income      = value x yield            (dividends + interest paid out)
  //   Withdrawal income = value x withdrawal rate  (spending that may include selling shares)
  // Monthly = yearly / 12, quarterly = yearly / 4; after tax = x (1 - tax rate).
  // Projection, one row per year: the withdrawal comes out at the start of the year, then
  //   end = (start - withdrawal) x (1 + total return) x (1 - fee).
  // "fixed": year-1 withdrawal = rate x starting value, raised by inflation each year after.
  // "percent": withdrawal = rate x that year's starting balance.
  // Checks: $500,000 at 3% yield = $15,000/yr = $1,250/mo; 4% = $20,000/yr = $1,666.67/mo;
  // year 1 end at 6% return, 0.5% fee = (500,000 - 20,000) x 1.06 x 0.995 = $506,256.00;
  // year 2 withdrawal with 2.5% inflation = $20,500. With 0% return/fee/inflation a 4%
  // withdrawal empties the portfolio in exactly 25 years.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function project(value, yieldRate, rate, ret, fee, inflation, method, years) {
    var rows = [], balance = value, depletedYear = 0, first = rate * value;
    var growth = (1 + ret) * (1 - fee);
    for (var y = 1; y <= years; y++) {
      var start = balance;
      var want = method === 'percent' ? rate * start : first * Math.pow(1 + inflation, y - 1);
      var draw = Math.min(want, start);
      var fromYield = Math.min(draw, yieldRate * start);
      balance = Math.max(0, (start - draw) * growth);
      if (balance < 0.005) balance = 0;
      rows.push({ year: y, start: start, draw: draw, fromYield: fromYield, sold: draw - fromYield, end: balance });
      if (!depletedYear && draw < want - 0.005) depletedYear = y;
      if (balance === 0) { if (!depletedYear && want > 0) depletedYear = y; break; }
    }
    return { rows: rows, end: balance, depletedYear: depletedYear };
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clear(id) {
    var el = document.getElementById(id);
    while (el.firstChild) el.removeChild(el.firstChild);
    return el;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text, i) {
      var cell = document.createElement(i === 0 ? 'th' : 'td');
      if (i === 0) cell.scope = 'row';
      cell.textContent = text;
      tr.appendChild(cell);
    });
    body.appendChild(tr);
  }

  function blank() {
    ['iiYieldMonthly', 'iiDrawMonthly', 'iiPrincipal', 'iiEnd'].forEach(function (id) { set(id, '–'); });
    set('iiPrincipalNote', ''); set('iiEndNote', '');
    document.getElementById('iiWarn').hidden = true;
    clear('iiPeriods'); clear('iiSchedule');
  }

  function update() {
    var value = num('iiValue'), yieldRate = num('iiYield'), rate = num('iiRate'), ret = num('iiReturn'),
        fee = num('iiFee'), inflation = num('iiInflation'), tax = num('iiTax'), years = num('iiYears');
    var method = document.getElementById('iiMethod').value;
    var msg = '';
    if (isNaN(value) || value < 0 || value > 1e11) msg = 'Enter a portfolio value of $0 or more.';
    else if (isNaN(yieldRate) || yieldRate < 0 || yieldRate > 50) msg = 'Enter a portfolio yield from 0 to 50%.';
    else if (isNaN(rate) || rate < 0 || rate > 50) msg = 'Enter a withdrawal rate from 0 to 50%.';
    else if (isNaN(ret) || ret < -50 || ret > 50) msg = 'Enter a total return from -50% to 50%.';
    else if (isNaN(fee) || fee < 0 || fee > 10) msg = 'Enter annual fees from 0 to 10%.';
    else if (isNaN(inflation) || inflation < 0 || inflation > 20) msg = 'Enter inflation from 0 to 20%.';
    else if (isNaN(tax) || tax < 0 || tax > 60) msg = 'Enter a tax rate from 0 to 60%.';
    else if (isNaN(years) || years < 1 || years > 60 || Math.round(years) !== years) msg = 'Enter 1 to 60 whole years to project.';
    var error = document.getElementById('iiError');
    error.hidden = !msg;
    if (msg) { error.textContent = msg; blank(); return; }

    var y = yieldRate / 100, w = rate / 100, t = tax / 100;
    var yieldYear = value * y, drawYear = value * w;
    set('iiYieldMonthly', money.format(yieldYear / 12));
    set('iiDrawMonthly', money.format(drawYear / 12));
    var gap = drawYear - yieldYear;
    if (gap > 0.005) {
      set('iiPrincipal', money.format(gap));
      set('iiPrincipalNote', 'Withdrawal minus yield income');
    } else {
      set('iiPrincipal', money.format(0));
      set('iiPrincipalNote', gap < -0.005 ? 'Yield covers it, with ' + money.format(-gap) + ' a year to spare' : 'Yield covers it exactly');
    }

    var periods = clear('iiPeriods');
    [['From yield', yieldYear], ['At ' + rate + '% withdrawal', drawYear]].forEach(function (r) {
      addRow(periods, [r[0], money.format(r[1]), money.format(r[1] / 4), money.format(r[1] / 12), money.format(r[1] / 12 * (1 - t))]);
    });

    var p = project(value, y, w, ret / 100, fee / 100, inflation / 100, method, years);
    var warn = document.getElementById('iiWarn');
    if (p.depletedYear) {
      set('iiEnd', money0.format(0));
      set('iiEndNote', 'Runs out in year ' + p.depletedYear);
      warn.textContent = 'At these settings the portfolio cannot keep paying the full withdrawal past year ' + p.depletedYear + '. A lower withdrawal rate or a higher return would make it last longer.';
      warn.hidden = false;
    } else {
      set('iiEnd', money0.format(p.end));
      set('iiEndNote', 'After ' + years + (years === 1 ? ' year' : ' years') + (p.end > value ? ', above where you started' : p.end < value ? ', below where you started' : ', the same as today'));
      warn.hidden = true;
    }
    var body = clear('iiSchedule');
    p.rows.forEach(function (r) {
      addRow(body, [String(r.year), money0.format(r.start), money0.format(r.draw), money0.format(r.fromYield), money0.format(r.sold), money0.format(r.end)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('iiForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
